  "upgrade.trialHistoryNote": "ለEssentials እየከፈሉ ወደ Business ከተንቀሳቀሱ፤ ተመሳሳይ የደንበኛ መለያ እና የሙከራ ታሪክ ይጠብቃሉ። Business ተጨማሪ የሰባት ቀን ሙከራ አያካትትም። የመጀመሪያ ሙከራዎ ገና እየሄደ ባለበት ወቅት ካሳደጉ፤ የመጀመሪያ ማብቂያ ቀኑ ዳግም አይዘጋጅም።",
  "upgrade.providerConfirmNote": "የዕቅድ ለውጦች ከአከፋፋይ አቅራቢ ማረጋገጫ ይፈልጋሉ። ማንኛውም የዋጋ ልዩነት፤ ተመጣጣኝ ማስተካከያ እና ተግባራዊ የሚሆንበት ቀን ለውጡን ከማጽደቅዎ በፊት መታየት አለባቸው። ማሳደግ ሁለተኛ በአንድ ጊዜ የሚሄድ ደንበኝነት ምዝገባ መፍጠር የለበትም።",
  "upgrade.chargedThroughProviderNote": "የዕቅድ ለውጦች በአከፋፋይ አቅራቢ በኩል ይከፈላሉ። ደንበኝነት ምዝገባዎን ከዚህ ገጽ በ«ደንበኝነት ምዝገባ ሰርዝ» ቁልፍ ስር ካለው አሁን ያለው ዕቅድዎ በታች በመጠቀም ወይም ከቅንብሮች መሰረዝ ይችላሉ። መሰረዝ በተከፈለበት ጊዜ መጨረሻ ላይ የወደፊት እድሳትን ያቆማል፤ መዳረሻዎን በአንድ ጊዜ በጭራሽ አያቋርጥም። ያሉት ነጻ የሥራ ቦታዎች እነዚህን አማራጮች በመመልከት አይከፈሉም።",
