  "import.eyebrow": "ዳታ",
  "import.title": "የማስገቢያ ማዕከል",
  "import.subtitleStart": "ሦስት የተለዩ የተመን ሉህ ስራዎች፣ ስለዚህ የዋጋ እርማት በጭራሽ እንደ የአክሲዮን ደረሰኝ ሊመጣ አይችልም። ሁሉም የሚደርሰው በ",
  "import.subtitleRest": " ብቻ ነው፣ እና ደረቅ ሙከራ እስኪያልፍ ድረስ ምንም አይጻፍም።",
  "import.createBusinessFirst": "በመጀመሪያ ንግድ ይፍጠሩ — የሚገቡ ምርቶች የንግድ ናቸው።",
  "import.createBusinessFirstShort": "በመጀመሪያ ንግድ ይፍጠሩ።",
  "import.whatEachDoes": "እያንዳንዱ ስራ ምን እንደሚያደርግ",
  "import.createTitle": "አዳዲስ ምርቶችን ይፍጠሩ",
  "import.createDesc": "በካታሎግ ውስጥ ገና ያልገቡ ረድፎችን ይጨምራል። ቀደም ሲል ጥቅም ላይ የዋሉ ተደጋጋሚ SKUዎች እና ባርኮዶች ይዘለላሉ፣ እና የመክፈቻ አክሲዮን እንደ ደረሰኝ በሚመርጡት ቦታ ሊደርስ ይችላል።",
  "import.updateTitle": "ያሉ ምርቶችን ያዘምኑ",
  "import.updateDesc": "እያንዳንዱን ረድፍ በSKU ወይም በመዝገብ መታወቂያ ያዛምዳል እና አሮጌውን እሴት ከተጠየቀው አዲስ እሴት ጎን ያሳያል። ባዶ ሴሎች ባዶዎችን እንዲያጸዱ ካልጠየቁ በቀር የተቀመጠውን እሴት ብቻቸውን ይተዋሉ፣ እና ብዛቶች በጭራሽ አይነኩም።",
