  "staff.access.pendingBody": "ይህ ንግድ ለኢሜይልዎ ገና ያልተነቃ ግብዣ አለው። ባለቤቱን የሰራተኞች ሁኔታዎን ንቁ እንዲያደርግ ይጠይቁ። እስከዚያ ድረስ እዚህ ምንም አይታይም።",
  "staff.access.pendingTitle": "ግብዣዎ ገና ንቁ አይደለም",
  "staff.access.signOut": "ውጣ",
  "staff.access.suspendedBody": "አስተዳዳሪ ይህን የሰራተኞች መለያ ለንቁ ንግድ አግዷል። ወደ ንቁ እንዲመልስዎት ይጠይቁት፣ ከዚያ እንደገና ይግቡ።",
  "staff.access.suspendedTitle": "መዳረሻዎ ቆሟል",
  "staff.addFirst": "የመጀመሪያውን የሰራተኞች አባል ጨምር",
  "staff.addMember": "የሰራተኞች አባል ጨምር",
  "staff.emptyBody": "ሰው ይጨምሩ፣ ሚና እና ከእሱ ጋር የሚሄዱ ፈቃዶች ይስጧቸው፣ እናም ወደዚህ ንግድ ለመግባት በኢሜይል ይጋበዛሉ።",
  "staff.emptyTitle": "እስካሁን ምንም ሰራተኞች የሉም",
  "staff.eyebrow": "ቡድን",
  "staff.how.p1": "እያንዳንዱ አባል ሚና እና የራሱ የፈቃድ ዝርዝር አለው፣ ስለዚህ ከሚና ጀምረው አዲስ ሚና ሳይፈጥሩ አንድ ነገር መቀየር ይችላሉ። ሚናን ማረም ቀድሞ በእሱ ላይ ያሉትን አባላት እንደገና አይጽፍም — የሚና ነባሪዎቻቸውን እንደገና ለመተግበር አባል ይክፈቱ።",
  "staff.how.p2": "ብጁ ሚናዎች የBusiness ባህሪ ናቸው፦ Essentials አምስቱን አብሮገነብ ሚናዎች ይጠቀማል (Owner፣ Manager፣ Stock clerk፣ Sales clerk፣ Viewer)።",
  "staff.how.p3": "ግብዣዎች በኢሜይል ይላካሉ። አባል መግባት የሚችለው ከተቀበለ በኋላ ብቻ ነው፣ እናም አንድን ሰው ከዚህ ዝርዝር ማስወገድ የመተግበሪያ መለያቸውን አይሰርዝም።",
  "staff.how.p4": "መደብር ሰው የተመደበበት ቦታ ነው። በካርዳቸው ላይ ይመዘገባል፤ ምን መክፈት እንደሚችሉ የሚወሰነው አሁንም በሚናቸው እና በፈቃዶቻቸው ነው።",
  "staff.how.p5": "ፈቃዶች እያንዳንዱ ሰው ምን መክፈት እንደሚችል ይወስናሉ፦ ከሚናቸው ውጭ ያሉ የምናሌ እቃዎች ተደብቀዋል፣ እናም የተዘጋ አድራሻ ከገጹ ይልቅ “በሚናዎ ላይ አይደለም” የሚል ማስታወቂያ ያሳያል። ለውጥ ሰውዬው መተግበሪያውን በሚቀጥለው ጊዜ ሲጭን ይተገበራል፤ አባልን ማገድ ሙሉ በሙሉ ያግዳቸዋል።",
  "staff.how.p6": "አስተዳዳሪዎች ሁሉንም መረጃ ማየት እና መቀየር፣ የመተግበሪያ ተጠቃሚዎችን እና ሚናዎችን ማስተዳደር ይችላሉ፣ እናም በሰራተኞች ሚና በፍፁም አይገደቡም። የሰራተኞች መዝገብ የሌለው ሰው — የአዲስ ንግድ ባለቤት — ሙሉ መዳረሻ ይይዛል።",
  "staff.howTitle": "ሰራተኞች እና ሚናዎች እንዴት እንደሚሰሩ",
